import{_ as t,o as e,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"JD7 简单密码","description":"简单 通过率：40.32% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 现在有一种密码变换算法。 九键手机键盘上的数字与字母的对应： 1 1， abc 2, def 3, ghi 4, jkl 5, mno 6, pqrs 7, tuv 8 wxyz 9, 0。","frontmatter":{"title":"JD7 简单密码","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：40.32% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 现在有一种密码变换算法。 九键手机键盘上的数字与字母的对应： 1 1， abc 2, def 3, ghi 4, jkl 5, mno 6, pqrs 7, tuv 8 wxyz 9, 0。","sidebarWeight":82,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD7 简单密码.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD7 简单密码.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD7 简单密码.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD7 简单密码.md"};function n(i,a,d,l,c,p){return e(),o("div",null,[...a[0]||(a[0]=[r('<div><h1 id="jd7-简单密码" tabindex="-1">JD7 简单密码 <a class="header-anchor" href="#jd7-简单密码" aria-label="Permalink to &quot;JD7 简单密码&quot;">​</a></h1><blockquote><p>本节目标：理解“JD7 简单密码”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：40.32% 时间限制：1秒 空间限制：32M 知识点==字符串====模拟== <strong>描述</strong> 现在有一种密码变换算法。 九键手机键盘上的数字与字母的对应： 1--1， abc--2, def--3, ghi--4, jkl--5, mno--6, pqrs--7, tuv--8 wxyz--9, 0--0，把密码中出现的小写字母都变成九键键盘对应的数字，如：a 变成 2，x 变成 9. 而密码中出现的大写字母则变成小写之后往后移一位，如：X ，先变成小写，再往后移一位，变成了 y ，例外：Z 往后移是 a 。 数字和其它的符号都不做变换。 数据范围： 输入的字符串长度满足 1≤�≤100 1≤<em>n</em>≤100 <strong>输入描述：</strong> 输入一组密码，长度不超过100个字符。 <strong>输出描述：</strong> 输出密码变换后的字符串 <strong>示例1</strong> 输入： YUANzhi1987 ==复制== 输出： zvbo9441987 ==复制==</p></blockquote><h1 id="九键手机键盘上的数字与字母的对应关系" tabindex="-1">九键手机键盘上的数字与字母的对应关系 <a class="header-anchor" href="#九键手机键盘上的数字与字母的对应关系" aria-label="Permalink to &quot;九键手机键盘上的数字与字母的对应关系&quot;">​</a></h1><p>passwordMap = { &quot;abc&quot;: 2, &quot;def&quot;: 3, &quot;ghi&quot;: 4, &quot;jkl&quot;: 5, &quot;mno&quot;: 6, &quot;pqrs&quot;: 7, &quot;tuv&quot;: 8, &quot;wxyz&quot;: 9, }</p><h1 id="构建字符到数字的映射字典" tabindex="-1">构建字符到数字的映射字典 <a class="header-anchor" href="#构建字符到数字的映射字典" aria-label="Permalink to &quot;构建字符到数字的映射字典&quot;">​</a></h1><p>char_to_num = {l: str(v) for k, v in passwordMap.items() for l in k}</p><p>def password_transform(password): transformed = &#39;&#39; for c in password: if c.islower(): # 对于小写字母，直接映射到数字 transformed += char_to_num[c] elif c.isupper(): # 对于大写字母，转换逻辑稍复杂</p><h1 id="首先将大写字母转为小写-然后根据规则移位" tabindex="-1">首先将大写字母转为小写，然后根据规则移位 <a class="header-anchor" href="#首先将大写字母转为小写-然后根据规则移位" aria-label="Permalink to &quot;首先将大写字母转为小写，然后根据规则移位&quot;">​</a></h1><p>if c == &#39;Z&#39;: c_next = &#39;a&#39; # 特殊处理Z到a的情况 else: c_next = chr(ord(c.lower()) + 1) # 其他大写字母转为小写后向后移一位</p><h1 id="如果转换后的小写字母存在于映射表中-转换为对应的数字" tabindex="-1">如果转换后的小写字母存在于映射表中，转换为对应的数字 <a class="header-anchor" href="#如果转换后的小写字母存在于映射表中-转换为对应的数字" aria-label="Permalink to &quot;如果转换后的小写字母存在于映射表中，转换为对应的数字&quot;">​</a></h1><p>transformed += c_next else: transformed += c # 数字和其他符号保持不变 return transformed</p><h1 id="输入一组密码" tabindex="-1">输入一组密码 <a class="header-anchor" href="#输入一组密码" aria-label="Permalink to &quot;输入一组密码&quot;">​</a></h1><p>password = input()</p><h1 id="输出密码变换后的字符串" tabindex="-1">输出密码变换后的字符串 <a class="header-anchor" href="#输出密码变换后的字符串" aria-label="Permalink to &quot;输出密码变换后的字符串&quot;">​</a></h1><p>print(password_transform(password))</p></div>',1)])])}const f=t(s,[["render",n]]);export{h as __pageData,f as default};
